INSERT INTO `recommendation_templates` (`id`, `title`, `data`, `created_at`, `updated_at`, `deleted_at`, `status`, `application_type`) VALUES
                                                                                                                                           (1, 'नाता प्रमाणित', '<div class=\"justify-content-center row\">\r\n<div class=\"col-lg-12\">\r\n<div class=\"card mb_30\">\r\n<div class=\"card-body p-3\">\r\n<div class=\"font-black\" id=\"printData\">\r\n<h5 style=\"text-align:center\"><span style=\"font-size:22px\"><strong>खण्ड: ख</strong></span></h5>\r\n\r\n<h5 style=\"text-align:center\"><span style=\"font-size:22px\"><strong>सिफारिसको नमुना ढाँचा</strong></span></h5>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/cropped-logo.png\" style=\"float:left; height:100px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:8rem; margin-top:0rem; text-align:center\"><strong><span style=\"font-size:20px\">....................पालिका<br />\r\nवडा नं. ....................को कार्यालय<br />\r\n........(कार्यालय रहेको स्थान) ............(जिल्ला)<br />\r\n........................ प्रदेश, नेपाल</span></strong></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:18px\"><strong>बिषय : नाता प्रमाणित। (१) </strong></span></p>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>जो जससँग सम्बन्धित छ।</strong></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:18px\">......................गाउँ/नगरपालिका वडा नं ......... अन्तर्गत ........... मा स्थायी बसोबास भएका श्री .................... ले तपसिलमा उल्लिखित व्यक्तिहरुबीच ................. प्रयोजनका लागि नाता प्रमाणित गरिदिन यस वडा कार्यालयमा दिनु भएको निवेदन अनुसार निजहरुबीच देहाय बमोजिम नाता रहेको व्यहोरा स्थानीय सरकार संचालन ऐन, २००७४ को दफा १२(२)ङ(१) बमोजिम प्रमाणित गरिन्छ ।</span></p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>देहाय</strong></span></p>\r\n\r\n<table border=\"1\" cellpadding=\"5\" cellspacing=\"0\" class=\"table table-bordered\" style=\"height:360px; width:1025px\">\r\n	<thead>\r\n		<tr>\r\n			<th scope=\"col\"><span style=\"font-size:18px\">निवेदक</span></th>\r\n			<th scope=\"col\"><span style=\"font-size:18px\">पिता</span></th>\r\n			<th scope=\"col\"><span style=\"font-size:18px\">माता</span></th>\r\n			<th scope=\"col\"><span style=\"font-size:18px\">दाई</span></th>\r\n			<th scope=\"col\"><span style=\"font-size:18px\">अन्य(नाता भएमा)</span></th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td><span style=\"font-size:18px\">हालसालै खिचेको पसपोर्ट साइजको फोटो</span></td>\r\n			<td><span style=\"font-size:18px\">हालसालै खिचेको पसपोर्ट साइजको फोटो</span></td>\r\n			<td><span style=\"font-size:18px\">हालसालै खिचेको पसपोर्ट साइजको फोटो</span></td>\r\n			<td><span style=\"font-size:18px\">हालसालै खिचेको पसपोर्ट साइजको फोटो</span></td>\r\n			<td><span style=\"font-size:18px\">हालसालै खिचेको पसपोर्ट साइजको फोटो</span></td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<div class=\"d-flex justify-content-end mt-2\">\r\n<p style=\"text-align:right\">&nbsp;</p>\r\n\r\n<p style=\"text-align:right\">&nbsp;</p>\r\n\r\n<p style=\"text-align:right\"><strong><span style=\"font-size:18px\">हस्ताक्षर ........................<br />\r\n(वडा अध्क्षय)</span></strong></p>\r\n</div>\r\n\r\n<div style=\"page-break-after:always\"><span style=\"display:none\">&nbsp;</span></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/cropped-logo.png\" style=\"float:left; height:100px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:8rem; margin-top:0rem; text-align:center\"><strong><span style=\"font-size:20px\">....................पालिका<br />\r\nवडा नं. ....................को कार्यालय<br />\r\n........(कार्यालय रहेको स्थान) ............(जिल्ला)<br />\r\n........................ प्रदेश, नेपाल</span></strong></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<h5 style=\"text-align:center\">&nbsp;</h5>\r\n\r\n<h5 style=\"text-align:center\">&nbsp;</h5>\r\n\r\n<h5 style=\"text-align:center\"><span style=\"font-size:20px\"><strong>Subject : Relation Certificate</strong></span></h5>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>To Whom It May Concern</strong></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:18px\">This is to certify that Mr/Mrs/Miss ................ resident of ............. Ward no. ................. is the native citizen of Nepal, as per the application proceeded in this office following members are the relatives of the applicant as mentioned below according to Local Government Operation Act, 2074.</span></p>\r\n\r\n<table border=\"1\" cellpadding=\"5\" cellspacing=\"0\" class=\"table table-bordered\" style=\"height:377px; width:1025px\">\r\n	<thead>\r\n		<tr>\r\n			<th scope=\"col\"><span style=\"font-size:18px\">Applicant</span></th>\r\n			<th scope=\"col\"><span style=\"font-size:18px\">Father</span></th>\r\n			<th scope=\"col\"><span style=\"font-size:18px\">Mother</span></th>\r\n			<th scope=\"col\"><span style=\"font-size:18px\">Brother</span></th>\r\n			<th scope=\"col\"><span style=\"font-size:18px\">Other</span></th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td><span style=\"font-size:18px\">हालसालै खिचेको पसपोर्ट साइजको फोटो</span></td>\r\n			<td><span style=\"font-size:18px\">हालसालै खिचेको पसपोर्ट साइजको फोटो</span></td>\r\n			<td><span style=\"font-size:18px\">हालसालै खिचेको पसपोर्ट साइजको फोटो</span></td>\r\n			<td><span style=\"font-size:18px\">हालसालै खिचेको पसपोर्ट साइजको फोटो</span></td>\r\n			<td><span style=\"font-size:18px\">हालसालै खिचेको पसपोर्ट साइजको फोटो</span></td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<div class=\"d-flex justify-content-end mt-2\">\r\n<p style=\"text-align:right\">&nbsp;</p>\r\n\r\n<p style=\"text-align:right\">&nbsp;</p>\r\n\r\n<p style=\"text-align:right\"><span style=\"font-size:18px\"><strong>sign ........................<br />\r\nWard Chairman</strong></span></p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>', '2022-11-27 03:01:17', '2022-11-27 04:22:49', NULL, 0, 'relationship_proof'),
                                                                                                                                           (2, 'नागरिकता सिफारिस', '<div class=\"justify-content-center row\">\r\n<div class=\"col-lg-12\">\r\n<div class=\"card mb_30\">\r\n<div class=\"card-body p-3\">\r\n<div class=\"font-black\" id=\"printData\">\r\n<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/cropped-logo.png\" style=\"float:left; height:100px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:8rem; margin-top:0rem; text-align:center\"><strong><span style=\"font-size:20px\">....................पालिका</span><br />\r\n<span style=\"font-size:16px\">वडा नं. ....................को कार्यालय</span><br />\r\n<span style=\"font-size:14px\">........(कार्यालय रहेको स्थान) ............(जिल्ला)<br />\r\n........................ प्रदेश, नेपाल</span></strong></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:16px\"><strong>बिषय : नागरिकता सिफारिस (२) </strong></span></p>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:18px\">नागरिकता सम्बन्धी सिफारिसहरु प्रचलित नागरिकता ऐन र नियमले तोकेको ढाँचामा गर्नुपर्नेछ । हाल नागरिकता ऐन, २०६३ र नियमावली, २०६३ प्रचलनमारहेकोले सो नियमावलीले तोकेको अनुसूची बमोजिम तोकिएको ढाँचामा सिफारिस गर्नुपर्नेछ ।</span></p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>', '2022-11-27 04:27:22', '2022-11-27 04:27:22', NULL, 0, 'citizenship_recommendation'),
                                                                                                                                           (3, 'बहाल करको लेखाजोखा', '<div class=\"justify-content-center row\">\r\n<div class=\"col-lg-12\">\r\n<div class=\"card mb_30\">\r\n<div class=\"card-body p-3\">\r\n<div class=\"font-black\" id=\"printData\">\r\n<div class=\"image mt-3\">\r\n<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/cropped-logo.png\" style=\"float:left; height:100px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:8rem; margin-top:0rem; text-align:center\"><strong><span style=\"font-size:20px\">....................पालिका</span><br />\r\n<span style=\"font-size:16px\">वडा नं. ....................को कार्यालय</span><br />\r\n<span style=\"font-size:14px\">........(कार्यालय रहेको स्थान) ............(जिल्ला)<br />\r\n........................ प्रदेश, नेपाल</span></strong></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:18px\"><strong>बिषय : बहाल करको लेखाजोखा । (३) </strong></span></p>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>जो जससँग सम्बन्धित छ ।</strong></span></p>\r\n\r\n<p><span style=\"font-size:18px\">व ...............गाउँ/नगरपालिका ............... वडा नं. ..............को ................. मा बस्ने श्री ................. ले यस गाउँ/नगरपालिकामा बहाल करको लेखाजोखा गरिदिनुहुन भनी दिनु भएको निवेदन अनुसार .................. र .............बीचभएको बहाल सम्झौता बमोजिम ................ देखि ................. सम्म जम्मा ...........वर्ष .......... महिनाको बहाल कर यस गाउँ/नगरपालिकाको नीयम अनुसार सम्झौता रकमको .................... प्रतिशतका दरले जम्मा रु. ....................बुझाई कर चुक्ता गरेको व्यहोरा स्थानीय सरकार संचालन ऐन, २०७४ को दफा १२(२)ङ(३) बमोजिम सिफारिस/प्रमाणित गरिन्छ ।</span></p>\r\n\r\n<div class=\"d-flex justify-content-end mt-2\">\r\n<p style=\"text-align:right\">&nbsp;</p>\r\n\r\n<p style=\"text-align:right\">&nbsp;</p>\r\n\r\n<p style=\"text-align:right\"><strong><span style=\"font-size:18px\">हस्ताक्षर ........................<br />\r\n(वडा अध्क्षय)</span></strong></p>\r\n</div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:18px\">नोट : सम्बन्धित फाँटका कर्मचारीबाट कर एकिन गरी सोको आधारमा मात्र प्रमाणित गर्नुपर्नेछ ।</span></p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>', '2022-11-27 04:39:11', '2022-11-27 04:39:11', NULL, 0, 'restored_tax'),
                                                                                                                                           (4, 'बन्द घर र कोठा खोल्न रोहवरमा बस्ने/बसेको प्रमाणित', '<div class=\"justify-content-center row\">\r\n<div class=\"col-lg-12\">\r\n<div class=\"card mb_30\">\r\n<div class=\"card-body p-3\">\r\n<div class=\"font-black\" id=\"printData\">\r\n<div class=\"image mt-3\">\r\n<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/cropped-logo.png\" style=\"float:left; height:100px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:8rem; margin-top:0rem; text-align:center\"><strong><span style=\"font-size:20px\">....................पालिका</span><br />\r\n<span style=\"font-size:16px\">वडा नं. ....................को कार्यालय</span><br />\r\n<span style=\"font-size:14px\">........(कार्यालय रहेको स्थान) ............(जिल्ला)<br />\r\n........................ प्रदेश, नेपाल</span></strong></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:18px\"><strong>बिषय : बन्द घर र कोठा खोल्न रोहवरमा बस्ने/बसेको प्रमाणित । (४) </strong></span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>जो जससँग सम्बन्धित छ ।</strong></span></p>\r\n\r\n<p><span style=\"font-size:18px\">...............गाउँ/नगरपालिका ............... वडा नं. ..............को ................. मा बस्ने श्री ................. ले बन्द घर/कोठा खुलाई पाउँ भनी दिएको निवेदन उपर मिति ............ मा बन्द घर वा कोठा खोल्ने सम