                                                                                                                                           (17, 'वडाबाट जारी हुने सिफारिस तथा अन्य कागजलाई अंग्रेजी भाषामा समेत सिफारिस तथा प्रमाणित गर्ने', '<div class=\"justify-content-center row\">\r\n<div class=\"col-lg-12\">\r\n<div class=\"card mb_30\">\r\n<div class=\"card-body p-3\">\r\n<div class=\"font-black\" id=\"printData\">\r\n<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/cropped-logo.png\" style=\"float:left; height:100px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:8rem; margin-top:0rem; text-align:center\"><strong><span style=\"font-size:20px\">....................पालिका</span><br />\r\n<span style=\"font-size:16px\">वडा नं. ....................को कार्यालय</span><br />\r\n<span style=\"font-size:14px\">........(कार्यालय रहेको स्थान) ............(जिल्ला)<br />\r\n........................ प्रदेश, नेपाल</span></strong></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:18px\"><strong>विषय : वडाबाट जारी हुने सिफारिस तथा अन्य कागजलाई अंग्रेजी भाषामा समेत सिफारिस तथा प्रमाणित गर्ने । (११) </strong></span></p>\r\n\r\n<p><span style=\"font-size:18px\">अंग्रेजी भाषामा उत्था गरी सम्बन्धित निकायमा सिफारिस वा प्रमाणित गरिदिने । उदाहरणका लागि,</span></p>\r\n\r\n<h4 style=\"text-align:center\"><span style=\"font-size:18px\"><strong>BIRTH CERTIFICATE</strong></span></h4>\r\n\r\n<h5><span style=\"font-size:18px\">TO WHOM IT MAY CONCERN</span></h5>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:18px\">This is to certify that Mr/Ms ............................................ Granddaughter/Grandson of ..................................., Daughter/Son of .............................., resident of ................. Municipality Ward No. ........... ..............District, .................. Province, Nepal, was born on ................................. Municipality Ward No ............., ................... District, Nepal according to his/her citizenship certificate according to Local Government Operation Act, 2074.</span></p>\r\n\r\n<h4 style=\"text-align:center\"><span style=\"font-size:18px\"><strong>PROPERTY VALUATION</strong></span></h4>\r\n\r\n<h5><span style=\"font-size:18px\">TO WHOM IT MAY CONCERN</span></h5>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:18px\">This is to certify that Mr ......................, is a permanent resident of ...................... Municipality Ward Np. 10, Province, Nepal. On his/her request for the total value of the properties owned by him/her in this .............................. Municipality is shown below. As per the field survey and investigation made by Ward Office, the current market value of property is as follows:</span></p>\r\n\r\n<h5><strong><u><span style=\"font-size:18px\">Valuation of Land &amp; Building</span></u></strong></h5>\r\n\r\n<table border=\"1\" cellpadding=\"5\" cellspacing=\"0\" class=\"my-2 table table-bordered\" style=\"height:176px; width:880px\">\r\n	<thead>\r\n		<tr>\r\n			<th rowspan=\"2\"><span style=\"font-size:18px\">SN</span></th>\r\n			<th rowspan=\"2\"><span style=\"font-size:18px\">Owner&#39;s Type</span></th>\r\n			<th rowspan=\"2\"><span style=\"font-size:18px\">Type of Property</span></th>\r\n			<th colspan=\"2\"><span style=\"font-size:18px\">Address</span></th>\r\n			<th rowspan=\"2\"><span style=\"font-size:18px\">Plot No.</span></th>\r\n			<th rowspan=\"2\"><span style=\"font-size:18px\">Area</span></th>\r\n			<th rowspan=\"2\"><span style=\"font-size:18px\">Rate(NRP)</span></th>\r\n			<th rowspan=\"2\"><span style=\"font-size:18px\">Total Valuation(NRP)</span></th>\r\n		</tr>\r\n		<tr>\r\n			<td><span style=\"font-size:18px\">Municipality</span></td>\r\n			<td><span style=\"font-size:18px\">ward</span></td>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td><span style=\"font-size:18px\">1</span></td>\r\n			<td><span style=\"font-size:18px\">ABC</span></td>\r\n			<td><span style=\"font-size:18px\">Land</span></td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td><span style=\"font-size:18px\">000</span></td>\r\n			<td><span style=\"font-size:18px\">0-0-0-0</span></td>\r\n			<td><span style=\"font-size:18px\">0000</span></td>\r\n			<td><span style=\"font-size:18px\">000000</span></td>\r\n		</tr>\r\n		<tr>\r\n			<td><span style=\"font-size:18px\">Total</span></td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p><span style=\"font-size:18px\">Total Valuation of Property is NRP : 0000000<br />\r\nToday&#39;s Exchange Rate US($) 1 = NRP : 00<br />\r\nwhich is equivalent to US ($): 000000 (Source: NRB)</span></p>\r\n\r\n<div class=\"d-flex justify-content-end mt-2\">\r\n<p style=\"text-align:right\">&nbsp;</p>\r\n\r\n<p style=\"text-align:right\"><span style=\"font-size:18px\"><strong>........................<br />\r\nWard Chairman</strong></span></p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<p>&nbsp;</p>', '2022-11-28 01:09:31', '2022-11-28 01:09:31', NULL, 0, 'birth_certificate_property_valuation'),
                                                                                                                                           (18, 'घर पाताल वा भत्के, भत्काएको प्रमाणित', '<div class=\"justify-content-center row\">\r\n<div class=\"col-lg-12\">\r\n<div class=\"card mb_30\">\r\n<div class=\"card-body p-3\">\r\n<div class=\"font-black\" id=\"printData\">\r\n<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/cropped-logo.png\" style=\"float:left; height:100px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:8rem; margin-top:0rem; text-align:center\"><strong><span style=\"font-size:20px\">....................पालिका</span><br />\r\n<span style=\"font-size:16px\">वडा नं. ....................को कार्यालय</span><br />\r\n<span style=\"font-size:14px\">........(कार्यालय रहेको स्थान) ............(जिल्ला)<br />\r\n........................ प्रदेश, नेपाल</span></strong></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:18px\"><strong>विषय : घर पाताल वा भत्के, भत्काएको प्रमाणित । (१२) </strong></span></p>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>श्री भूमिसुधार/मालपोत कार्यालय,<br />\r\n.......................</strong></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:18px\">...............गाउँ/नगरपालिका ............... वडा नं. .............. बस्ने श्री ................. को नाति/नातिनी .............. को छोरा/छोरी श्री ................. को नाममा ................ गाउँ/नगरपालिका वडा नं ....... को ............ मा रहेको कित्ता नं. ................. क्षेत्रफ़ल ............. मा रहेको .............. वर्गफूटको घर मिति .............. मा पाताल वा भत्केको व्यहोरा निजको निवेदन र प्रविधिक प्रतिवेदन/स्थालगत निरीक्षण प्रतिवेदन/मिति .............. मा गरिएको स्थानीय सर्जमिन मुचुल्काको आधारमा स्थानीय सरकार संचालन ऐन, २०७४ को दफा १२(२)ङ(१२) बमोजिम प्रमाणित गरिन्छ ।</span></p>\r\n\r\n<div class=\"d-flex justify-content-end mt-2\">\r\n<p style=\"text-align:right\">&nbsp;</p>\r\n\r\n<p style=\"text-align:right\"><strong><span style=\"font-size:18px\">हस्ताक्षर ........................<br />\r\n(वडा अध्क्षय)</span></strong></p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>', '2022-11-28 01:12:21', '2022-11-28 01:12:21', NULL, 0, 'house_destroy'),
                                                                                                                                           (19, 'व्यत्तिगत विवरण प्रमाणित वा सिफारिस', '<div class=\"justify-content-center row\">\r\n<div class=\"col-lg-12\">\r\n<div class=\"card mb_30\">\r\n<div class=\"card-body p-3\">\r\n<div class=\"font-black\" id=\"printData\">\r\n<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/cropped-logo.png\" style=\"float:left; height:100px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:8rem; margin-top:0rem; text-align:center\"><strong><span style=\"font-size:20px\">....................पालिका</span><br />\r\n<span style=\"font-size:16px\">वडा नं. ....................को कार्यालय</span><br />\r\n<span style=\"font-size:14px\">........(कार्यालय रहेको स्थान) ............(जिल्ला)<br />\r\n........................ प्रदेश, नेपाल</span></strong></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:18px\"><strong>विषय : व्यत्तिगत विवरण प्रमाणित वा सिफारिस । (१३) </strong></span></p>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>जो जससँग सम्बन्धित छ ।</strong></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:18px\">व्यत्तिगत के के विवरण प्रमाणित गर्नुपर्ने हो सो को प्रमाण राखेर सो को आधारमा मात्र स्थानीय सरकार संचालन ऐन, २००७४ को दफा १२(२)ङ(१३) बमोजिम प्रमाणित वा सिफारिस गरिदिनु पर्नेछ । जस्तै : कसैको शैक्षिक योग्यता प्रमाणित गर्नुपर्ने भएमा निजको शैक्षिक योग्यता हेरी सो को प्रमाण आधारमा मात्र गर्ने ।</span></p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>', '2022-11-28 01:14:33', '2022-11-28 01:14:33', NULL, 0, 'personal_detail_certificate_recommendation'),
                                                                                                                                           (20, 'नक्सामा घर कायम गर्ने सिफारिस', '<div class=\"justify-content-center row\">\r\n<div class=\"col-lg-12\">\r\n<div class=\"card mb_30\">\r\n<div class=\"card-body p-3\">\r\n<div class=\"font-black\" id=\"printData\">\r\n<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/cropped-logo.png\" style=\"float:left; height:100px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:8rem; margin-top:0rem; text-align:center\"><strong><span style=\"font-size:20px\">....................पालिका</span><br />\r\n<span style=\"font-size:16px\">वडा नं. ....................को कार्यालय</span><br />\r\n<span style=\"font-size:14px\">........(कार्यालय रहेको स्थान) ............(जिल्ला)<br />\r\n........................ प्रदेश, नेपाल</span></strong></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:18px\"><strong>विषय : नक्सामा घर कायम गर्ने सिफारिस । (१४) </strong></span></p>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>श्री नापी कार्यलय,<br />\r\n...................... ।</strong></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:18px\">............................ गाउँ/नगरपालिका वडा नं. ............अन्तर्गत श्री ........................................................ को नाती/नातिनी श्री .............