                                                                                                                                           (31, 'नामसारी सिफारिस', '<div class=\"justify-content-center row\">\r\n<div class=\"col-lg-12\">\r\n<div class=\"card mb_30\">\r\n<div class=\"card-body p-3\">\r\n<div class=\"font-black\" id=\"printData\">\r\n<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/cropped-logo.png\" style=\"float:left; height:100px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:8rem; margin-top:0rem; text-align:center\"><strong><span style=\"font-size:20px\">....................पालिका</span><br />\r\n<span style=\"font-size:16px\">वडा नं. ....................को कार्यालय</span><br />\r\n<span style=\"font-size:14px\">........(कार्यालय रहेको स्थान) ............(जिल्ला)<br />\r\n........................ प्रदेश, नेपाल</span></strong></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<h5 style=\"text-align:center\">&nbsp;</h5>\r\n\r\n<h5 style=\"text-align:center\">&nbsp;</h5>\r\n\r\n<h5 style=\"text-align:center\"><span style=\"font-size:18px\"><strong>विषय : नामसारी सिफारिस । (२४) </strong></span></h5>\r\n\r\n<h5 style=\"text-align:center\">&nbsp;</h5>\r\n\r\n<h5><span style=\"font-size:18px\"><strong>श्री मालपोत कार्यलय,<br />\r\n................... ।</strong></span></h5>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:18px\">............................ गाउँ/नगरपालिका वडा नं. ............बस्ने श्री ...................................... को नाति/नातिनी श्री ..................... को छोरा/छोरी श्री ............................... को मिति .................................... मा मृत्यु भएको हुनाले निज मृतकका नाममा रहेको तल उल्लेखित विवरणको घरजग्गा नामसारीको लागि श्री ....................................... ले निवेदन दिनुभएकोमा ........................................... पालिकाबाट गरिएको नाता प्रमाणित विवरण अनुसार निज मृतकको नाममा रहेको सो घर/जग्गा प्रचलित कानुन बमोजिम हकदारहरुको नाममा नामसारीको लागि स्थानीय सरकार संचालन ऐन. २०७४ को दफा १२(२) ङ (२४) बमोजिम सिफारिस साथ अनुरोध गरिन्छ ।</span></p>\r\n\r\n<h5><u><strong><span style=\"font-size:18px\">मृतकका हकदारहरुको विवरण</span></strong></u></h5>\r\n\r\n<table border=\"1\" cellpadding=\"5\" cellspacing=\"0\" class=\"my-2 table table-bordered\" style=\"height:108px; width:889px\">\r\n	<thead>\r\n		<tr>\r\n			<th><span style=\"font-size:18px\">क्र. स</span></th>\r\n			<th><span style=\"font-size:18px\">हकदारहरुको नाम</span></th>\r\n			<th><span style=\"font-size:18px\">नाता</span></th>\r\n			<th><span style=\"font-size:18px\">बाबु/पति को नाम</span></th>\r\n			<th><span style=\"font-size:18px\">बाजे/ससुरा को नाम</span></th>\r\n			<th><span style=\"font-size:18px\">ना.प्र.प.नं/जारी मिति/जिल्ला</span></th>\r\n			<th><span style=\"font-size:18px\">कैफियत</span></th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<h5><u><strong><span style=\"font-size:18px\">नामसारी गर्ने घर/जग्गाको विवरण</span></strong></u></h5>\r\n\r\n<table border=\"1\" cellpadding=\"5\" cellspacing=\"0\" class=\"my-2 table table-bordered\" style=\"height:110px; width:886px\">\r\n	<thead>\r\n		<tr>\r\n			<th><span style=\"font-size:18px\">क्र. स</span></th>\r\n			<th><span style=\"font-size:18px\">वडा नं.</span></th>\r\n			<th><span style=\"font-size:18px\">सिट नं.</span></th>\r\n			<th><span style=\"font-size:18px\">कि. नं.</span></th>\r\n			<th><span style=\"font-size:18px\">क्षेत्रफल</span></th>\r\n			<th><span style=\"font-size:18px\">कैफियत</span></th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<div class=\"d-flex justify-content-end mt-2\">\r\n<p style=\"text-align:right\">&nbsp;</p>\r\n\r\n<p style=\"text-align:right\"><span style=\"font-size:18px\"><strong>हस्ताक्षर.......................<br />\r\n(वडा अध्यक्ष)</strong></span></p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>', '2022-11-28 02:27:24', '2022-11-28 02:27:24', NULL, 0, 'transfer_recommendation'),
                                                                                                                                           (32, 'जग्गाको हक सम्बन्धमा सिफारिस', '<div class=\"justify-content-center row\">\r\n<div class=\"col-lg-12\">\r\n<div class=\"card mb_30\">\r\n<div class=\"card-body p-3\">\r\n<div class=\"font-black\" id=\"printData\">\r\n<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/cropped-logo.png\" style=\"float:left; height:100px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:8rem; margin-top:0rem; text-align:center\"><strong><span style=\"font-size:20px\">....................पालिका</span><br />\r\n<span style=\"font-size:16px\">वडा नं. ....................को कार्यालय</span><br />\r\n<span style=\"font-size:14px\">........(कार्यालय रहेको स्थान) ............(जिल्ला)<br />\r\n........................ प्रदेश, नेपाल</span></strong></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:18px\"><strong>विषय : जग्गाको हक सम्बन्धमा सिफारिस । (२५) </strong></span></p>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>जो जस सँग सम्बन्ध छ ।</strong></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:18px\">........... गाउँ/नगरपालिका वडा नं. ............ बस्ने श्री .............. को नाति/नातिनी श्री ................... को छोरा/छोरी श्री ................ को नाममा दर्ता श्रेष्ता कायम रहेको तल उल्लिखित विवरणको जग्गाको हक सम्बन्धमा सिफारिस गरिदिनका लागि श्री .................. ले निवेदन दिनुभएकोमा .................. गाउँ/नगरपालिकाबाट गरिएको नाता प्रमाणित विवरण र स्थानीय सर्जमिन मुचुल्का समेतका आधारमा सो जग्गाको हक देहाय बमोजिम हुन स्थानीय सरकार संचालन ऐन, २०७४ को दफा १२(२)ङ(२५) बमोजिम सिफारिस गरिन्छ ।</span></p>\r\n\r\n<h4><u><span style=\"font-size:18px\"><strong>हकदारहरुको विवरण</strong></span></u></h4>\r\n\r\n<table border=\"1\" cellpadding=\"5\" cellspacing=\"0\" class=\"table table-bordered\" style=\"height:159px; width:876px\">\r\n	<thead>\r\n		<tr>\r\n			<th scope=\"col\"><span style=\"font-size:18px\">क्र.स</span></th>\r\n			<th scope=\"col\"><span style=\"font-size:18px\">हकदारहरुको नाम</span></th>\r\n			<th scope=\"col\"><span style=\"font-size:18px\">नाता</span></th>\r\n			<th scope=\"col\"><span style=\"font-size:18px\">बावु/पति को नाम</span></th>\r\n			<th scope=\"col\"><span style=\"font-size:18px\">ना.प्र.प.नं/जारी<br />\r\n			मिति/जिल्ला</span></th>\r\n			<th scope=\"col\"><span style=\"font-size:18px\">कैफियत</span></th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n			<td>&nbsp;</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<h4><u><span style=\"font-size:18px\"><strong>नामसारी गर्ने जग्गाको विवरण</strong></span></u></h4>\r\n\r\n<table border=\"1\" cellpadding=\"5\" cellspacing=\"0\" class=\"table table-bordered\" style=\"height:118px; width:877px\">\r\n	<thead>\r\n		<tr>\r\n			<th scope=\"col\"><span style=\"font-size:18px\">क्र.स</span></th>\r\n			<th scope=\"col\"><span style=\"font-size:18px\">वडा नं.</span></th>\r\n			<th scope=\"col\"><span style=\"font-size:18px\">सिट नं.</span></th>\r\n			<th scope=\"col\"><span style=\"font-size:18px\">क्षेत्रफल</span></th>\r\n			<th scope=\"col\"><span style=\"font-size:18px\">कैफियत</span></th>\r\n		</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"text-align:right\">&nbsp;</td>\r\n			<td style=\"text-align:right\">&nbsp;</td>\r\n			<td style=\"text-align:right\">&nbsp;</td>\r\n			<td style=\"text-align:right\">&nbsp;</td>\r\n			<td style=\"text-align:right\">&nbsp;</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<div class=\"d-flex justify-content-end mt-2\">\r\n<p style=\"text-align:right\">&nbsp;</p>\r\n\r\n<p style=\"text-align:right\"><strong><span style=\"font-size:18px\">हस्ताक्षर ........................<br />\r\n(वडा अध्क्षय)</span></strong></p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>', '2022-11-28 02:32:21', '2022-11-28 02:32:21', NULL, 0, 'land_owner_right_recommendation'),
                                                                                                                                           (33, 'उधोग ठाउँसारी सिफारिस', '<div class=\"justify-content-center row\">\r\n<div class=\"col-lg-12\">\r\n<div class=\"card mb_30\">\r\n<div class=\"card-body p-3\">\r\n<div class=\"font-black\" id=\"printData\">\r\n<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/cropped-logo.png\" style=\"float:left; height:100px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:8rem; margin-top:0rem; text-align:center\"><strong><span style=\"font-size:20px\">....................पालिका</span><br />\r\n<span style=\"font-size:16px\">वडा नं. ....................को कार्यालय</span><br />\r\n<span style=\"font-size:14px\">........(कार्यालय रहेको स्थान) ............(जिल्ला)<br />\r\n........................ प्रदेश, नेपाल</span></strong></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:18px\"><strong>विषय : उधोग ठाउँसारी सिफारिस । (२६) </strong></span></p>\r\n\r\n<p style=\"text-align:center\">&nbsp;</p>\r\n\r\n<p><span style=\"font-size:18px\"><strong>जो जससँग सम्बन्धित छ ।</strong></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:18px\">...............गाउँ/नगरपालिका वडा नं. ............. बस्ने श्री ................. ले .............. गाउँ/नगरपालिका वडा नं ........ को ................... मा रहेको ....................... नामको उधोगको ठाउँसारी जाने/आउने भएकोले सिफारिस माग गर्नुभएकोमा सो उधोग ......