                                                                                                                                           (34, 'आधारभूत विधालय खोल्ने सिफारिस', '<div class=\"justify-content-center row\">\r\n<div class=\"col-lg-12\">\r\n<div class=\"card mb_30\">\r\n<div class=\"card-body p-3\">\r\n<div class=\"font-black\" id=\"printData\">\r\n<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/cropped-logo.png\" style=\"float:left; height:100px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:8rem; margin-top:0rem; text-align:center\"><strong><span style=\"font-size:20px\">....................पालिका</span><br />\r\n<span style=\"font-size:16px\">वडा नं. ....................को कार्यालय</span><br />\r\n<span style=\"font-size:14px\">........(कार्यालय रहेको स्थान) ............(जिल्ला)<br />\r\n........................ प्रदेश, नेपाल</span></strong></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<h5 style=\"text-align:center\">&nbsp;</h5>\r\n\r\n<h5 style=\"text-align:center\"><span style=\"font-size:18px\"><strong>विषय : आधारभूत विधालय खोल्ने सिफारिस । (२७) </strong></span></h5>\r\n\r\n<h5 style=\"text-align:center\">&nbsp;</h5>\r\n\r\n<h5><span style=\"font-size:18px\"><strong>श्री ................................ गाउँनगर कार्यपालिकाको कार्यलय,<br />\r\n......................................... ।</strong></span></h5>\r\n\r\n<p><span style=\"font-size:18px\">............................ गाउँ/नगरपालिका वडा नं. ............ को ................................... मा आधारभुत विधालय खोल्नका लागि स्थनीय भद्रभलादमी सहितको बैठकको निर्णय अनुसार माग भई आएकोमा सो स्थानमा आधारभुत विधालय खोल्ने उपयुक्त भएको भनी यस वडा कार्यालयको मिति ........................... मा निर्णय भएकोले सोहि अनुसार आधारभुतन विधालय खोल्ने स्थानीय सरकार संचालन ऐन. २०७४ को दफा १२(२) ङ (२७) बमोजिम सिफारिस साथ अनुरोध गरिन्छ ।</span></p>\r\n\r\n<div class=\"d-flex justify-content-end mt-2\">\r\n<p style=\"text-align:right\"><span style=\"font-size:18px\"><strong>हस्ताक्षर.......................<br />\r\n(वडा अध्यक्ष)</strong></span></p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>', '2022-11-28 03:04:45', '2022-11-28 03:04:45', NULL, 0, 'primary_school_recommendation'),
                                                                                                                                           (35, 'जग्गा मुल्यांकन/प्रमाणित', '<div class=\"justify-content-center row\">\r\n<div class=\"col-lg-12\">\r\n<div class=\"card mb_30\">\r\n<div class=\"card-body p-3\">\r\n<div class=\"font-black\" id=\"printData\">\r\n<div class=\"flex-container\" style=\"display:flex\">\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:0rem; margin-right:4rem; margin-top:0rem; text-align:center\"><img alt=\"\" src=\"http://localhost:8000/storage/photos/1/cropped-logo.png\" style=\"float:left; height:100px; width:110px\" /></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-right:8rem; margin-top:0rem; text-align:center\"><strong><span style=\"font-size:20px\">....................पालिका</span><br />\r\n<span style=\"font-size:16px\">वडा नं. ....................को कार्यालय</span><br />\r\n<span style=\"font-size:14px\">........(कार्यालय रहेको स्थान) ............(जिल्ला)<br />\r\n........................ प्रदेश, नेपाल</span></strong></div>\r\n\r\n<div class=\"item-auto\" style=\"flex:1 1 auto; margin-bottom:0rem; margin-left:4rem; margin-right:0rem; margin-top:0rem; text-align:center\">&nbsp;</div>\r\n</div>\r\n\r\n<h5 style=\"text-align:center\">&nbsp;</h5>\r\n\r\n<h5 style=\"text-align:center\">&nbsp;</h5>\r\n\r\n<h5 style=\"text-align:center\"><span style=\"font-size:18px\"><strong>विषय : जग्गा मुल्यांकन/प्रमाणित । (२८) </strong></span></h5>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h5><span style=\"font-size:18px\"><strong>श्री जो जससंग सम्बन्धित छ ।</strong></span></h5>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:18px\">............................ गाउँ/नगरपालिका वडा नं. ............ को ................................... मा स्थायी ठेगाना भएका श्री .............................. ले आफ्नो तपसिलमा उल्लेखित जग्गाको मुल्यांकन/ प्रमाणित गरिदिन भनि निवेदन पेश गर्नुभएकोमा सो जग्गाको मुल्यांकन /